def transform(grid):
    h = len(grid)
    w = 7
    out = [[0] * w for _ in range(h)]
    marker = next((c for row in grid for c, v in enumerate(row) if v == 5), 8)
    col = max(0, min(w - 1, marker - 8))
    out[0][col] = 5

    patterns = {
        ((1, 1, 0), (1, 0, 1), (0, 1, 0)): (3, "right"),  # A
        ((1, 0, 1), (1, 0, 1), (1, 1, 1)): (2, "left"),   # B
        ((1, 0, 1), (0, 1, 0), (0, 1, 0)): (2, "down"),   # C
        ((1, 1, 1), (0, 1, 0), (1, 0, 1)): (4, "left"),   # D
    }

    objects = []
    starts = list(range(0, h - 2, 4))
    for base_col in (0, 4):
        for r in starts:
            cells = [(rr, cc) for rr in range(r, r + 3)
                     for cc in range(base_col, base_col + 3)
                     if grid[rr][cc] not in (0, 4, 5)]
            if not cells:
                continue
            color = grid[cells[0][0]][cells[0][1]]
            shape = tuple(tuple(
                1 if grid[r + dr][base_col + dc] == color else 0
                for dc in range(3)) for dr in range(3))
            if shape in patterns:
                length, direction = patterns[shape]
                objects.append((color, length, direction))

    # The input objects are read down the left column, then down the right.
    row, col = 0, max(0, min(w - 1, marker - 8))
    for color, length, direction in objects:
        if direction == "down":
            for k in range(1, length + 1):
                rr = row + k
                if rr < h:
                    out[rr][col] = color
            row += length
        else:
            rr = row + 1
            step = 1 if direction == "right" else -1
            for k in range(length):
                cc = col + step * k
                if rr < h and 0 <= cc < w:
                    out[rr][cc] = color
            row += 1
            col += step * (length - 1)
    return out
